test('sibling authority creates a fresh peer-tenant admin session before catalog and mode admission',async()=>{const{prepareV09SiblingAssessmentAuthority}=require('./secureshopMailHtmlRenderedProduction');const peerScope={launchId:randomUUID(),scenarioId:randomUUID(),generation:3,platformOwnerId:17,platformSessionId:19},tenantId=randomUUID(),principalId=randomUUID(),calls=[];let mode={mode:'vuln',revision:'1'},enabled=false,adminContext=null;const identityMigration={query:async(sql,args)=>{calls.push([sql,args]);if(sql.startsWith('SELECT'))return{rows:[{sessionId:'19',tenantId,principalId,slug:'peer_tenant',ownerId:17}]};if(sql.includes('INSERT INTO secureshop_auth.principals')){assert.equal(args[3],'controlled-password-hash');return{rows:[{shopUserId:23}]};}assert.match(sql,/INSERT INTO secureshop_auth\.tenant_memberships/);return{rows:[{tenantId,principalId:args[1],shopUserId:23,role:'admin',revision:'1'}]};}},publicationModes={getPrincipalMode:async actual=>{assert.deepEqual(actual,{sessionId:'19',tenantId,principalId});return{...mode};},setPrincipalMode:async(actual,input)=>{assert.deepEqual(actual,{sessionId:'19',tenantId,principalId});assert.equal(input.expectedRevision,mode.revision);mode={mode:input.mode,revision:String(Number(mode.revision)+1)};return{...mode};},getEvaluationScope:async(owner,key,scope)=>{assert.equal(owner,17);assert.equal(key,'secureshop_agent_security');assert.equal(scope,peerScope);return{mode:mode.mode};}},peerAuth={login:async input=>{assert.match(input.username,/^v09_peer_admin_[0-9a-f]{8}$/);assert.match(input.password,/^v09-peer-[0-9a-f]{8}-password$/);adminContext={fresh:true,username:input.username};return{context:adminContext};},establishTenantContext:async context=>{assert.equal(context,adminContext);return{role:'admin',tenantId,ownerId:17};}},catalog={list:async actual=>{assert.equal(actual,adminContext);return{objectives:[{objectiveId:'ss_mail_agent_html_injection',qualification:'native-browser-judge',enabled:false,revision:'1'}]};},set:async(actual,input)=>{assert.equal(actual,adminContext);assert.deepEqual(input,{objectiveId:'ss_mail_agent_html_injection',enabled:true,expectedRevision:'1'});enabled=true;return{...input,qualification:'native-browser-judge'};}},application={readiness:async()=>({ready:true,modeCapability:{effectiveMode:mode.mode},objectiveReadiness:{ss_mail_agent_html_injection:enabled}})},context={};const authority=await prepareV09SiblingAssessmentAuthority({peerScope,identityRuntime:{},identityMigration,publicationModes,hashPassword:async()=> 'controlled-password-hash',createPeerAuth:({tenantSlug})=>{assert.equal(tenantSlug,'peer_tenant');return peerAuth;},createPeerCatalog:({authService})=>{assert.equal(authService,peerAuth);return catalog;},readEligibility:async(_pool,scope,ids)=>{assert.equal(scope,peerScope);assert.deepEqual(ids,['ss_mail_agent_html_injection']);return enabled?ids:[];}});assert.equal(mode.mode,'fixed');await authority.assertFixedReadiness(application,context);await authority.activateVulnerable(application,context);await authority.assertVulnerable(application,context);assert.equal(mode.mode,'vuln');assert.equal(calls.length,3);assert(calls[1][0].includes('INSERT INTO secureshop_auth.principals'));assert(calls[2][0].includes('INSERT INTO secureshop_auth.tenant_memberships'));});
